<?php
declare(strict_types=1);
if(!defined('CMS_ENTRY'))exit;
function safe_url(mixed $value,bool $image=false):string{$v=txt($value,2000);if($v===''||preg_match('/[\x00-\x20\x7f\\\\]/',$v))return '';if($image){if(preg_match('~^/media/[a-f0-9]{32}\.(png|jpg|gif|webp)$~D',$v))return $v;foreach(catalog()['starters'] as $s)if($v==='/assets/starter-images/'.$s['id'].'.jpg')return $v;return '';}
 if(str_starts_with($v,'/')&&!str_starts_with($v,'//')&&!in_array('..',explode('/',$v),true))return $v;if(str_starts_with($v,'#'))return $v;
 if(preg_match('/^(mailto:|tel:)/i',$v))return $v;
 if(filter_var($v,FILTER_VALIDATE_URL)&&in_array(strtolower(parse_url($v,PHP_URL_SCHEME)??''),['http','https'],true)&&!parse_url($v,PHP_URL_USER)&&!parse_url($v,PHP_URL_PASS))return $v;return '';}
function page_path(array $page):string{return empty($page['slug'])?'/':'/'.$page['slug'].'/';}
function choose(mixed $v,array $choices,string $default):string{return is_string($v)&&in_array($v,$choices,true)?$v:$default;}
function default_site():array{$site=catalog()['site'];$site['url']=request_origin().base_path();$site['revision']=uid();return $site;}
function validate_site(array $input,array $pages,array $categories):array{$s=default_site();foreach(['name','tagline','description','email','phone','address','footer','copyright','language','formEndpoint'] as $key)$s[$key]=txt($input[$key]??'', $key==='description'?2000:1000);if(!$s['name'])fail(400,'Website name is required.');$url=txt($input['url']??'',2000);if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true)||parse_url($url,PHP_URL_QUERY)||parse_url($url,PHP_URL_FRAGMENT)||parse_url($url,PHP_URL_USER))fail(400,'Enter a valid website URL.');$s['url']=rtrim($url,'/');
 if(!preg_match('/^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/D',$s['language']))fail(400,'Enter a valid language code.');
 $s['theme']=choose($input['theme']??'',array_column(catalog()['themes'],'id'),'minimal');$s['font']=choose($input['font']??'',['sans','serif','mono'],'sans');$s['direction']=($input['direction']??'')==='rtl'?'rtl':'ltr';$s['entity']=choose($input['entity']??'',['Organization','LocalBusiness','Person'],'Organization');$s['accent']=txt($input['accent']??'');if(!preg_match('/^#[a-f0-9]{6}$/iD',$s['accent']))fail(400,'Use a six-digit accent colour.');
 foreach(['logo','favicon','socialImage'] as $key)$s[$key]=safe_url($input[$key]??'',true);$s['formEndpoint']=safe_url($s['formEndpoint']);if($s['formEndpoint']&&!str_starts_with($s['formEndpoint'],'https://')&&!localhost_request())fail(400,'Form endpoints must use HTTPS.');
 $s['social']=[];foreach(array_slice(is_array($input['social']??null)?$input['social']:[],0,12) as $item){$url=safe_url($item['url']??'');if($url)$s['social'][]=['label'=>txt($item['label']??'',60),'url'=>$url];}
 foreach(catalog()['chrome'] as $key=>$items)$s[$key]=choose($input[$key]??'',array_column($items,'id'),$items[0]['id']);
 $s['starterLayout']=choose($input['starterLayout']??'',['split','centered','card','resume','editorial'],'split');$s['menuStyle']=choose($input['menuStyle']??'',['auto','normal','mega'],'auto');$s['menuAlign']=($input['menuAlign']??'')==='center'?'center':'right';foreach(['stickyHeader','showSearch'] as $key)$s[$key]=!empty($input[$key]);$s['bundledArtwork']=($input['bundledArtwork']??true)!==false;
 $total=0;foreach(['menus','footerMenus'] as $key)$s[$key]=validate_menu($input[$key]??[],$pages,$categories,0,$total);$s['revision']=uid();return $s;}
function validate_menu(mixed $items,array $pages,array $categories,int $depth,int &$total):array{if(!is_array($items)||$depth>2)fail(400,'Menus support up to three levels.');$out=[];foreach($items as $i){if(!is_array($i)||++$total>120)fail(400,'Invalid menu or too many entries.');$label=txt($i['label']??'',120);if(!$label)fail(400,'A menu label is required.');$page=txt($i['page']??'',80);$category=txt($i['category']??'',80);if($page&&!in_array($page,array_column($pages,'id'),true))fail(400,'A menu page is missing.');if($category&&!in_array($category,array_column($categories,'id'),true))fail(400,'A menu category is missing.');$out[]=['id'=>txt($i['id']??'',80)?:uid(),'label'=>$label,'page'=>$page,'category'=>$category,'url'=>safe_url($i['url']??''),'description'=>txt($i['description']??'',500),'layout'=>choose($i['layout']??'',['auto','dropdown','mega'],'auto'),'columns'=>max(2,min(4,(int)($i['columns']??3))),'icon'=>choose($i['icon']??'',['spark','grid','heart','arrow','check','star'],''),'highlight'=>!empty($i['highlight']),'newTab'=>!empty($i['newTab']),'nofollow'=>!empty($i['nofollow']),'children'=>!empty($i['children'])?validate_menu($i['children'],$pages,$categories,$depth+1,$total):[]];}return $out;}
function validate_page(array $input,array $pages,array $categories):array{
 $id=txt($input['id']??'',80)?:uid();if(!preg_match('/^[a-zA-Z0-9-]+$/D',$id))fail(400,'Invalid page ID.');$slug=strtolower(txt($input['slug']??'',160));if($slug!==''&&!preg_match('~^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$~D',$slug))fail(400,'Use lowercase URL segments.');if(in_array(explode('/',$slug)[0],['admin','api','assets','media','preview','starter-preview','category','search','app','install','recover','router.php','index.php','blog'],true)||in_array($slug,['404','robots.txt','sitemap.xml'],true))fail(400,'This URL is reserved.');foreach($pages as $p)if($p['id']!==$id&&$p['slug']===$slug)fail(409,'Another page already uses this URL.');
 $title=txt($input['title']??'',200);if(!$title)fail(400,'A page title is required.');$sections=$input['sections']??null;if(!is_array($sections)||count($sections)>80)fail(400,'A page supports up to 80 sections.');$out=[];
 foreach($sections as $s){if(!is_array($s)||!in_array($s['type']??'',['hero','text','features','image','gallery','timeline','testimonials','faq','cta','contact','links','collection','pricing'],true))fail(400,'Unknown section type.');$r=['id'=>txt($s['id']??'',80)?:uid(),'type'=>$s['type'],'hidden'=>!empty($s['hidden'])];foreach(['eyebrow','title','text','button','alt'] as $key)$r[$key]=txt($s[$key]??'',$key==='text'?20000:1000);$r['image']=safe_url($s['image']??'',true);$r['link']=safe_url($s['link']??'');$r['linkPage']=txt($s['linkPage']??'',80);$r['linkCategory']=txt($s['linkCategory']??'',80);if($r['linkPage']&&$r['linkPage']!==$id&&!in_array($r['linkPage'],array_column($pages,'id'),true))fail(400,'A button page is missing.');if($r['linkCategory']&&!in_array($r['linkCategory'],array_column($categories,'id'),true))fail(400,'A category is missing.');$r['collectionKind']=choose($s['collectionKind']??'',['page','post','product','service','project','member'],'post');$r['itemLimit']=max(1,min(24,(int)($s['itemLimit']??6)));$r['items']=[];
 foreach(array_slice(is_array($s['items']??null)?$s['items']:[],0,40) as $i){if(!is_array($i))continue;$r['items'][]=['title'=>txt($i['title']??'',300),'text'=>txt($i['text']??'',5000),'image'=>safe_url($i['image']??'',true),'alt'=>txt($i['alt']??'',500),'icon'=>choose($i['icon']??'',['spark','grid','heart','arrow','check','star'],'spark')];}
 if($s['type']==='pricing'){$r['pricing']=validate_pricing($s['pricing']??[],$pages,$id);}$out[]=$r;
 }
 $cats=array_slice(array_values(array_unique(is_array($input['categories']??null)?$input['categories']:[])),0,20);foreach($cats as $cat)if(!in_array($cat,array_column($categories,'id'),true))fail(400,'An assigned category is missing.');$seo=is_array($input['seo']??null)?$input['seo']:[];
 return ['id'=>$id,'revision'=>uid(),'title'=>$title,'slug'=>$slug,'status'=>($input['status']??'')==='published'?'published':'draft','kind'=>choose($input['kind']??'',['page','post','project','service','member','product'],'page'),'starterId'=>array_key_exists($input['starterId']??'',catalog()['bundles'])?$input['starterId']:'','starterKey'=>txt($input['starterKey']??'',80),'starterLayout'=>choose($input['starterLayout']??'',['split','centered','card','resume','editorial'],''),'categories'=>$cats,'tags'=>array_slice(array_values(array_unique(array_map(fn($x)=>txt($x,60),is_array($input['tags']??null)?$input['tags']:[]))),0,30),'author'=>txt($input['author']??'',200),'date'=>preg_match('/^\d{4}-\d{2}-\d{2}$/D',$input['date']??'')?$input['date']:gmdate('Y-m-d'),'excerpt'=>txt($input['excerpt']??'',2000),'sections'=>$out,'seo'=>['title'=>txt($seo['title']??'',200),'description'=>txt($seo['description']??'',1000),'noindex'=>!empty($seo['noindex']),'image'=>safe_url($seo['image']??'',true)],'updatedAt'=>stamp()];
}
function validate_pricing(mixed $data,array $pages,string $pageId):array{$data=is_array($data)?$data:[];$result=['layout'=>choose($data['layout']??'',['cards','rows','stacked','comparison','compact'],'cards'),'skin'=>choose($data['skin']??'',['clean','soft','outline','contrast'],'clean'),'currency'=>txt($data['currency']??'',12),'note'=>txt($data['note']??'',2000),'plans'=>[]];foreach(array_slice(is_array($data['plans']??null)?$data['plans']:[],0,12) as $p){if(!is_array($p))continue;$r=[];foreach(['name'=>150,'description'=>1500,'price'=>100,'previousPrice'=>100,'period'=>100,'badge'=>80,'button'=>120,'linkPage'=>80] as $key=>$max)$r[$key]=txt($p[$key]??'',$max);$r['name']=$r['name']?:'Plan';$r['link']=safe_url($p['link']??'');if($r['linkPage']&&$r['linkPage']!==$pageId&&!in_array($r['linkPage'],array_column($pages,'id'),true))fail(400,'A pricing button destination is missing.');$r['featured']=!empty($p['featured']);$features=[];$source=is_string($p['features']??null)?explode("\n",$p['features']):($p['features']??[]);foreach(array_slice(is_array($source)?$source:[],0,40) as $f){if(is_string($f)){$parts=explode('|',$f,2);$f=['label'=>$parts[0],'value'=>$parts[1]??'Included'];}if(!is_array($f))continue;$label=txt($f['label']??'',150);if($label)$features[$label]=['label'=>$label,'value'=>txt($f['value']??'',300)];}$r['features']=array_values($features);$result['plans'][]=$r;}return $result;}
function references(array $page):array{$r=[];foreach($page['sections'] as $s){if(!empty($s['linkPage']))$r[]=$s['linkPage'];foreach($s['pricing']['plans']??[] as $p)if(!empty($p['linkPage']))$r[]=$p['linkPage'];}return $r;}
function menu_uses(array $items,string $key,string $id):bool{foreach($items as $i)if(($i[$key]??'')===$id||menu_uses($i['children']??[],$key,$id))return true;return false;}
function starter(string $id,string $prefix='',bool $draft=false,array $existingCategories=[],bool $preview=false):array{
 $bundle=catalog()['bundles'][$id]??null;if(!$bundle)fail(400,'Unknown subject template.');if($prefix!==''&&(!preg_match('/^[a-z0-9]+(-[a-z0-9]+)*$/D',$prefix)||in_array($prefix,['admin','api','assets','media','app','preview','starter-preview','category','search','blog','install','recover'],true)))fail(400,'Choose a unique lowercase folder name.');
 $map=[];foreach($bundle['pages'] as $p)$map[$p['id']]=$preview?$p['id']:uid();foreach($bundle['categories'] as $c){$found=array_values(array_filter($existingCategories,fn($x)=>$x['slug']===$c['slug']));$map[$c['id']]=$found?$found[0]['id']:($preview?$c['id']:uid());}
 $walk=function(mixed $value)use(&$walk,$map){if(is_string($value))return $map[$value]??$value;if(!is_array($value))return $value;$out=[];foreach($value as $k=>$v)$out[$k]=$walk($v);return $out;};$bundle=$walk($bundle);
 foreach($bundle['pages'] as &$p){$p['slug']=$prefix?($prefix.($p['slug']?'/'.$p['slug']:'')):$p['slug'];$p['status']=$draft?'draft':'published';$p['revision']=uid();foreach($p['sections'] as &$s)$s['id']=uid();unset($s);}unset($p);
 return $bundle;
}
function all_pages(array $site,array $pages,array $categories,array $links):array{$result=$pages;$live=array_values(array_filter($pages,fn($p)=>$p['status']==='published'));$make=fn($slug,$title,$text,$sections)=>['id'=>'generated-'.$slug,'slug'=>$slug,'title'=>$title,'status'=>'published','kind'=>'page','seo'=>['description'=>$text],'sections'=>array_merge([['type'=>'hero','title'=>$title,'text'=>$text]],$sections)];foreach($categories as $c){$selected=array_values(array_filter($live,fn($p)=>in_array($c['id'],$p['categories']??[],true)));$result[]=$make('category/'.$c['slug'],$c['name'],$c['description']??'',[['type'=>'collection','title'=>'','collectionKind'=>'all','selected'=>$selected],['type'=>'links','linkCategory'=>$c['id']]]);} $posts=array_values(array_filter($live,fn($p)=>($p['kind']??'')==='post'));if($posts)$result[]=$make('blog','Journal','News, notes and ideas.',[['type'=>'collection','selected'=>$posts]]);$search=$make('search','Find something good.','Search this website.',[['type'=>'search']]);$search['seo']['noindex']=true;$result[]=$search;return $result;}
